@charset "UTF-8";.content_view-SBPLoader__loader-block {
    align-items: center;
    display: flex;
    height: inherit;
    justify-content: center;
    padding: 40px
}

.content_view-SBPLoader__loader-block__icon {
    animation: content_view-SBPLoader__loader-animation 1s linear 0s infinite;
    color: #107f8c;
    height: 24px;
    width: 24px
}

@keyframes content_view-SBPLoader__loader-animation {
    0% {
        transform: rotate(0deg)
    }

    to {
        transform: rotate(1turn)
    }
}

