@keyframes ui-light-CommonButton__spin {
    0% {
        transform: rotate(0deg)
    }

    to {
        transform: rotate(1turn)
    }
}

.ui-light-CommonButton__commonButton {
    align-items: center;
    border-radius: 100px;
    box-sizing: border-box;
    cursor: pointer;
    display: inline-flex;
    font-family: SB Sans Interface,sans-serif;
    font-weight: 600;
    justify-content: center;
    position: relative;
    text-align: center;
    text-decoration: none;
    vertical-align: middle
}

.ui-light-CommonButton__commonButton:focus-visible {
    box-shadow: 0 0 0 3px #1358bf;
    outline: 0
}

.ui-light-CommonButton__commonButton span {
    align-items: center;
    display: flex;
    justify-content: center
}

.ui-light-CommonButton__color {
    background-color: var(--bg-color);
    border: 2px solid var(--border-color);
    color: var(--text-color)
}

.ui-light-CommonButton__color:hover:not([disabled=disabled]) {
    background-color: var(--bg-hover-color);
    border: 2px solid var(--border-hover-color);
    color: var(--text-hover-color)
}

.ui-light-CommonButton__color:active:not([disabled=disabled]) {
    background-color: var(--bg-active-color);
    border: 2px solid var(--border-active-color);
    color: var(--text-active-color)
}

.ui-light-CommonButton__disabled {
    background-color: transparent;
    border: 1px solid #a3a3a3;
    color: #a3a3a3;
    cursor: default
}

.ui-light-CommonButton__loaded {
    background-color: var(--bg-color);
    border: 2px solid var(--border-color);
    color: var(--text-color);
    cursor: default
}

.ui-light-CommonButton__size-extra-small {
    font-size: 12px;
    line-height: 16px
}

.ui-light-CommonButton__size-extra-small--default {
    gap: 8px;
    padding: 6px 10px
}

.ui-light-CommonButton__size-extra-small--round {
    padding: 6px
}

.ui-light-CommonButton__size-small {
    font-size: 14px;
    line-height: 16px
}

.ui-light-CommonButton__size-small--default {
    gap: 8px;
    padding: 10px 14px
}

.ui-light-CommonButton__size-small--round {
