.ui-light-CommonButton__size-large {
    font-size: 16px;
    line-height: 24px
}

.ui-light-CommonButton__size-large--default {
    gap: 16px;
    padding: 14px 30px
}

.ui-light-CommonButton__size-large--round {
    padding: 14px
}

.ui-light-CommonButton__fill {
    border-radius: inherit;
    box-sizing: border-box;
    color: var(--loader-color);
    display: block;
    height: 100%;
    left: 0;
    pointer-events: none;
    position: absolute;
    top: 0;
    transition: border-color .1s cubic-bezier(.8,0,.2,1),background-color .1s cubic-bezier(.8,0,.2,1);
    width: 100%
}

.ui-light-CommonButton__loader {
    animation-duration: 1s;
    animation-iteration-count: infinite;
    animation-name: ui-light-CommonButton__spin;
    animation-timing-function: linear;
    height: 24px;
    left: 50%;
    margin-left: -12px;
    margin-top: -12px;
    position: absolute;
    top: 50%;
    width: 24px;
    z-index: 1
}

.ui-light-CommonButton__invisible {
    opacity: 0
}

.ui-light-CommonButton__round_content {
    height: var(--icon-size);
