.ui-light-SegmentedControl__SegmentedControl {
    background-color: rgba(0,0,0,.04);
    border-radius: 30px;
    display: flex;
    flex-wrap: nowrap;
    position: relative;
    width: fit-content
}

.ui-light-SegmentedControl__SegmentedControlTab {
    align-items: center;
    background: transparent;
    border: none;
    border-radius: 30px;
    box-sizing: border-box;
    color: #222;
    cursor: pointer;
    display: flex;
    font-family: SB Sans Interface,sans-serif;
    gap: 10px;
    justify-content: center;
    white-space: nowrap
}

.ui-light-SegmentedControl__SegmentedControlTabIcon {
    align-items: center;
    display: flex;
    justify-content: center;
    padding-left: 3px
}

.ui-light-SegmentedControl__SegmentedControlTab:not(.ui-light-SegmentedControl__active):hover {
    background-color: rgba(0,0,0,.12)
}

.ui-light-SegmentedControl__extra-small {
    font-size: 12px;
    line-height: 16px;
    padding: 8px 12px
}

.ui-light-SegmentedControl__small {
    font-size: 14px;
    line-height: 20px;
    padding: 10px 16px
}

.ui-light-SegmentedControl__dropdown {
    background-color: #fff;
    border-radius: 8px;
    box-shadow: 0 20px 28px -6px rgba(0,0,0,.08),0 0 4px rgba(0,0,0,.08);
    display: none;
    font-family: SB Sans Interface,sans-serif;
    max-height: 288px;
    min-width: 160px;
    overflow-y: scroll;
    position: absolute;
    right: 0;
    z-index: 100
}

.ui-light-SegmentedControl__dropdown::-webkit-scrollbar {
    display: none
}

.ui-light-SegmentedControl__dropdown_extra-small {
    top: 40px
}

.ui-light-SegmentedControl__dropdown_small {
    top: 48px
}

.ui-light-SegmentedControl__dropdownItem {
    background-color: transparent;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    display: block;
    padding: 8px;
    text-align: left;
    width: 100%
}

.ui-light-SegmentedControl__dropdownItem:focus-visible,.ui-light-SegmentedControl__dropdownItem:not(.ui-light-SegmentedControl__active):hover {
    background-color: rgba(0,0,0,.04)
