.MlchtUI-Breadcrumbs {
    display: flex;
    align-items: center
}

.MlchtUI-Breadcrumbs__Separator {
    margin: 0 9px;
    padding: 0;
    color: rgba(0,0,0,.36);
    cursor: default
}

.MlchtUI-Breadcrumbs__IconBackground_paint {
    position: relative;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(0,0,0,.04)
}

.MlchtUI-Breadcrumbs__IconSeparator_paint {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 16px;
    height: 16px;
    transform: translate(-50%,-50%)
}

.MlchtUI-Breadcrumbs__IconSeparator_paint svg {
    vertical-align: initial
}

.MlchtUI-Breadcrumbs__IconSeparator_paint svg path {
    fill: #000
}

.MlchtUI-Breadcrumbs__IconSeparator:not(.MlchtUI-Breadcrumbs__IconSeparator_paint) path {
    fill: rgba(0,0,0,.36)
}

.MlchtUI-Breadcrumbs__Section {
    display: flex;
    align-items: center;
    min-height: 40px;
    margin: 0;
    padding: 1px 3px;
    font-family: SB Sans Interface,sans-serif;
    font-weight: 400;
    font-size: 16px;
    line-height: 20px;
    text-decoration: none;
    color: #1f1f22;
    cursor: pointer;
    user-select: none;
    transition: color .2s cubic-bezier(.8,0,.2,1)
}

.MlchtUI-Breadcrumbs__Section:focus-visible {
    outline: none
}

.MlchtUI-Breadcrumbs__Section:focus-visible:not(.MlchtUI-Breadcrumbs_active) {
    border-radius: 8px;
    box-shadow: 0 0 0 3px #1358bf
}

