    color: #198cfe
}

.MlchtUI-Breadcrumbs__Section_link:active {
    color: #0f5498
}

.MlchtUI-Breadcrumbs__Section_active {
    color: rgba(0,0,0,.36);
    cursor: default
}

.MlchtUI-Breadcrumbs_contextTheme_dark .MlchtUI-Breadcrumbs__Separator {
    color: hsla(0,0%,100%,.5)
}

.MlchtUI-Breadcrumbs_contextTheme_dark .MlchtUI-Breadcrumbs__Separator .MlchtUI-Breadcrumbs__IconBackground_paint {
